from __future__ import annotations
from math import sqrt
from typing import Sequence

def normalized_concurrence(amplitudes: Sequence[complex]) -> float:
    """Normalize four amplitudes and return pure-state concurrence."""
    if len(amplitudes) != 4:
        raise ValueError("exactly four amplitudes are required")
    norm_sq = sum(abs(z) ** 2 for z in amplitudes)
    if norm_sq == 0.0:
        raise ValueError("the zero vector has no normalization")
    a, b, c, d = (z / sqrt(norm_sq) for z in amplitudes)
    return 2.0 * abs(a * d - b * c)

from __future__ import annotations
from typing import Sequence

def product_state_residual(amplitudes: Sequence[complex]) -> float:
    """Return |alpha*delta-beta*gamma|, zero exactly at rank one."""
    if len(amplitudes) != 4:
        raise ValueError("exactly four amplitudes are required")
    a, b, c, d = amplitudes
    return abs(a * d - b * c)

def is_numerically_separable(amplitudes: Sequence[complex], tolerance: float = 1e-12) -> bool:
    """Tolerance-aware numerical rank-one test."""
    if tolerance < 0.0:
        raise ValueError("tolerance must be nonnegative")
    return product_state_residual(amplitudes) <= tolerance

from __future__ import annotations

def integer_obstruction_gap(concurrence: float) -> float:
    """Distance of a concurrence value in [0,1] from {0,1}."""
    if not 0.0 <= concurrence <= 1.0:
        raise ValueError("concurrence must lie in [0,1]")
    return min(concurrence, 1.0 - concurrence)

def obstructs_integer_equality(concurrence: float, tolerance: float = 1e-12) -> bool:
    """Test whether a value is separated from every integer by tolerance."""
    return integer_obstruction_gap(concurrence) > tolerance

